def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_op = op[-1]
    last_me = me[-1]
    remaining = 100 - n

    # Recent window
    w = 10 if n >= 10 else n
    recent = op[-w:]
    recent_op_c = recent.count('C')
    recent_op_d = w - recent_op_c

    # Total opponent stats
    total_op_c = op.count('C')
    total_op_d = n - total_op_c
    op_rate = total_op_c / n

    # Streaks at end
    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break
    streak_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            streak_c += 1
        else:
            break

    # === Early game: build cooperation ===
    if n < 3:
        return 'C'

    # === Detect always-defector (or near) ===
    if total_op_d == n:
        return 'D'
    if n >= 8 and total_op_d >= n - 1:
        return 'D'

    # === Detect always-cooperator / near ===
    if total_op_d == 0:
        # Exploit at tail, otherwise cooperate to keep them nice
        if remaining <= 3:
            return 'D'
        # Occasional probe to see if forgiving
        if n > 15 and n % 11 == 0:
            return 'D'
        return 'C'

    # === Final rounds: exploit known cooperators, defend vs defectors ===
    if remaining <= 3:
        if op_rate > 0.6:
            return 'D'
        if streak_d >= 1:
            return 'D'
        if streak_c >= 1 and op_rate > 0.35:
            return 'D'
        return 'C'

    if remaining <= 6:
        if op_rate > 0.55:
            return 'D'
        if streak_d >= 2:
            return 'D'
        if op_rate < 0.3:
            return 'D'
        return 'C'

    # === Strong defector response ===
    if op_rate < 0.25:
        return 'D'
    if recent_op_d >= w - 1:
        return 'D'

    # === Long mutual defection: try to break out ===
    # But only if opponent has shown any cooperation historically
    if streak_d >= 3:
        if total_op_c >= 3 and remaining > 10:
            # periodic reconciliation attempts
            if streak_d % 4 == 3:
                return 'C'
        return 'D'

    # === Opponent defected last round ===
    if last_op == 'D':
        # forgive single defection if opponent is otherwise cooperative
        if streak_d == 1 and op_rate > 0.7:
            return 'C'
        # otherwise retaliate; strong punishment if rate moderate
        if streak_d >= 2:
            return 'D'
        # single defection: retaliate with high probability
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # === Opponent cooperated last round ===
    if last_op == 'C':
        # If we defected last and they still cooperated, they're forgiving.
        # Groom them and cooperate back, but exploit opportunistically.
        if last_me == 'D':
            return 'C'
        # If opponent overwhelmingly cooperative, occasionally probe late
        if op_rate > 0.8 and remaining > 10:
            if n % 17 == 0 and rng.random() < 0.4:
                return 'D'
            return 'C'
        # Moderate opponent: cooperate to keep cooperation going
        if op_rate > 0.5:
            return 'C'
        # Mixed: mostly cooperate
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    return 'C'
